    vals = rec['values']
    if 'ProductName' not in vals or 'Value' not in vals or 'Weight' not in vals:
        raise ValueError('Missing product fields in record')
    pname = vals['ProductName']
    try:
        v = int(vals['Value'])
        w = int(vals['Weight'])
